export const FORMBRICKS_SURVEYS_FILTERS_KEY_LS = "formbricks-surveys-filters";
export const FORMBRICKS_WORKFLOWS_FILTERS_KEY_LS = "formbricks-workflows-filters";
export const FORMBRICKS_ENVIRONMENT_ID_LS = "formbricks-environment-id";
export const FORMBRICKS_WORKSPACE_ID_LS = "formbricks-workspace-id";
export const FORMBRICKS_LOGGED_IN_WITH_LS = "formbricks-logged-in-with";

// Server-readable mirror of the "last active workspace". The proxy sets this from the
// /workspaces/[workspaceId] path so server components (e.g. the workspace-agnostic org-settings
// shell) can resolve the current workspace during render — localStorage is browser-only.
export const FORMBRICKS_WORKSPACE_ID_COOKIE = "formbricks-workspace-id";

// Server-readable "last active organization", set by the proxy from /organizations/[organizationId]
// paths and cleared again on any /workspaces/[workspaceId] visit. It only exists while the most recent
// org-scoped visit is newer than the last workspace visit — e.g. an organization with no workspace
// yet (its landing page) — which is exactly when the workspace cookie above names the wrong
// organization. Account settings, which carry no organization in the URL, read it first.
export const FORMBRICKS_ORGANIZATION_ID_COOKIE = "formbricks-organization-id";
export const getFormattedErrorMessage = (result: {
  serverError?: string;
  validationErrors?: unknown;
}): string => {
  let message = "";

  if (result.serverError) {
    message = result.serverError;
  } else {
    const errors = result.validationErrors as
      | Record<string, { _errors?: string[] } | string[] | undefined>
      | undefined;
    message = Object.keys(errors || {})
      .map((key) => {
        const value = errors?.[key];
        if (key === "_errors" && Array.isArray(value)) return value.join(", ");
        const fieldErrors =
          value && typeof value === "object" && "_errors" in value ? value._errors : undefined;
        const fieldError = fieldErrors?.join(", ");
        if (key && fieldError?.toLowerCase().startsWith(key.toLowerCase())) {
          return fieldError;
        }
        const keyPrefix = key ? `${key}: ` : "";
        return `${keyPrefix}${fieldError}`;
      })
      .join("\n");
  }

  return message;
};
import { TActionClassPageUrlRule } from "@formbricks/types/action-classes";

export const testURLmatch = (
  testUrl: string,
  pageUrlValue: string,
  pageUrlRule: TActionClassPageUrlRule,
  t: (key: string) => string
): boolean => {
  let regex: RegExp;

  switch (pageUrlRule) {
    case "exactMatch":
      return testUrl === pageUrlValue;
    case "contains":
      return testUrl.includes(pageUrlValue);
    case "startsWith":
      return testUrl.startsWith(pageUrlValue);
    case "endsWith":
      return testUrl.endsWith(pageUrlValue);
    case "notMatch":
      return testUrl !== pageUrlValue;
    case "notContains":
      return !testUrl.includes(pageUrlValue);
    case "matchesRegex":
      try {
        regex = new RegExp(pageUrlValue);
      } catch {
        throw new Error(t("workspace.actions.invalid_regex"));
      }

      return regex.test(testUrl);
    default:
      throw new Error(t("workspace.actions.invalid_match_type"));
  }
};

/**
 * Upper bound on a callback URL, in characters (ENG-2783).
 *
 * A callback rides in a request line, and nginx's `large_client_header_buffers` defaults to `4 8k` with
 * the rule that a request line must fit inside ONE buffer — so an over-long callback comes back as a
 * bare `414 Request-URI Too Large`, a blank page with nothing to act on. Rejecting it here turns that
 * into something diagnosable instead: `proxy.ts` answers `400 {"error":"Invalid callback URL"}`, and
 * the auth flows fall back to `WEBAPP_URL` the same way they do for any other invalid callback.
 *
 * 2048 is the conventional safe maximum, and it is not a new constraint on this codebase:
 * `resendVerificationEmailAction` has capped its callback at 2000 since it was written. The widest
 * legitimate callback in the app is an invite link, `/invite?token=<jwt>`, which measures ~640
 * characters with a long address — so this leaves roughly threefold headroom.
 */
export const MAX_CALLBACK_URL_LENGTH = 2048;

// Helper function to validate callback URLs
export const getValidatedCallbackUrl = (
  url: string | null | undefined,
  WEBAPP_URL: string
): string | null => {
  if (!url) {
    return null;
  }

  try {
    const parsedWebAppUrl = new URL(WEBAPP_URL);
    const isAbsoluteUrl = /^[a-zA-Z][a-zA-Z\d+\-.]*:/.test(url);
    const isRootRelativePath = url.startsWith("/");

    // Reject ambiguous non-URL values like "foo" while still allowing safe root-relative paths.
    if (!isAbsoluteUrl && !isRootRelativePath) {
      return null;
    }

    const parsedUrl = isAbsoluteUrl ? new URL(url) : new URL(url, parsedWebAppUrl.origin);
    const allowedSchemes = ["https:", "http:"];
    const allowedOrigins = new Set([parsedWebAppUrl.origin]);

    if (!allowedSchemes.includes(parsedUrl.protocol)) {
      return null;
    }

    if (!allowedOrigins.has(parsedUrl.origin)) {
      return null;
    }

    if (parsedUrl.username || parsedUrl.password) {
      return null;
    }

    // A same-origin absolute URL can still carry a scheme-relative pathname ("//evil.example").
    // Consumers that reduce the URL to pathname+search+hash (login's router.push) would then
    // navigate off-origin. Reject it here so every consumer is protected. Backslash and
    // dot-segment variants normalize to a "//" pathname before this check. (ENG-1636)
    if (parsedUrl.pathname.startsWith("//")) {
      return null;
    }

    const validatedCallbackUrl = parsedUrl.toString();

    // Measured on what we RETURN, not on what came in. `toString()` percent-encodes, up to ninefold
    // for a 3-byte character, so an input under the cap can leave it: 258 characters ending in 227 CJK
    // characters comes back as 2074. Checking the input instead made the function reject its own
    // output, so a callback accepted here failed the re-validation in `completeSsoRecovery` and the
    // user landed on the app root rather than where they were going.
    return validatedCallbackUrl.length > MAX_CALLBACK_URL_LENGTH ? null : validatedCallbackUrl;
  } catch {
    return null;
  }
};

export const isStringUrl = (url: string): boolean => {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
};
/**
 * Marketing attribution captured on the auth pages (login / signup).
 *
 * Only the whitelisted keys below are ever read or stored. These are non-personal,
 * non-user-unique marketing values (source / campaign / landing page), so the
 * `fb_attribution` cookie is a functional attribution cookie rather than user tracking.
 *
 * The cookie is written client-side (first-touch) on the auth pages and read
 * server-side at PostHog capture time for `user_signed_up` / `user_signed_in`.
 */

export const ATTRIBUTION_PARAM_KEYS = [
  "page",
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "initial_source",
  "entry_page",
] as const;

export type TAttributionKey = (typeof ATTRIBUTION_PARAM_KEYS)[number];

export const ATTRIBUTION_COOKIE_NAME = "fb_attribution";

// 30 minutes: long enough to survive the OAuth redirect round-trip and any
// login/signup navigation, short enough that stale attribution cannot bleed onto
// a later (or different) user's events on a shared browser. See getAttributionPropertiesFromCookies
// consumers which also clear the cookie once it has been captured.
export const ATTRIBUTION_COOKIE_MAX_AGE = 60 * 30;

// Guard against oversized cookie values polluting events.
const MAX_ATTRIBUTION_VALUE_LENGTH = 256;

// Browsers silently reject cookies whose total size exceeds ~4KB. Keep the encoded
// value comfortably under that (accounting for the name and attributes).
export const MAX_ATTRIBUTION_COOKIE_VALUE_LENGTH = 3500;

type TCookieStore = {
  get: (name: string) => { value: string } | undefined;
};

/**
 * Extract only the whitelisted, non-empty attribution params from a URLSearchParams.
 */
export const pickAttributionParams = (params: URLSearchParams | null | undefined): Record<string, string> => {
  const result: Record<string, string> = {};
  if (!params) return result;

  for (const key of ATTRIBUTION_PARAM_KEYS) {
    const value = params.get(key);
    if (value && value.trim().length > 0) {
      result[key] = value.trim().slice(0, MAX_ATTRIBUTION_VALUE_LENGTH);
    }
  }

  return result;
};

/**
 * Read the attribution cookie server-side and return validated, whitelisted
 * properties ready to spread into a PostHog event's properties. Returns an empty
 * object when the cookie is missing or malformed.
 */
export const getAttributionPropertiesFromCookies = (cookieStore: TCookieStore): Record<string, string> => {
  // Next's cookie store already percent-decodes the value, so `raw` is the plain
  // JSON string the client wrote (via encodeURIComponent). Do NOT decode again here —
  // a second decode corrupts any value that legitimately contains a `%XX` sequence.
  const raw = cookieStore.get(ATTRIBUTION_COOKIE_NAME)?.value;
  if (!raw) return {};

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return {};
  }

  if (typeof parsed !== "object" || parsed === null) return {};

  const record = parsed as Record<string, unknown>;
  const result: Record<string, string> = {};

  for (const key of ATTRIBUTION_PARAM_KEYS) {
    const value = record[key];
    if (typeof value === "string" && value.trim().length > 0) {
      result[key] = value.trim().slice(0, MAX_ATTRIBUTION_VALUE_LENGTH);
    }
  }

  return result;
};

/**
 * Build a query-string suffix (e.g. `page=home&utm_source=x`, no leading `?`/`&`)
 * from the current attribution params, for forwarding across the login/signup links.
 * Returns an empty string when there is nothing to forward.
 */
export const buildAttributionQuerySuffix = (params: URLSearchParams | null | undefined): string => {
  const picked = pickAttributionParams(params);
  const search = new URLSearchParams(picked);
  return search.toString();
};
"use client";

import { CheckIcon } from "lucide-react";
import { useMemo } from "react";
import { useTranslation } from "react-i18next";

interface PasswordChecksProps {
  password: string | null;
}

const PASSWORD_REGEX = {
  UPPER_AND_LOWER: /^(?=.*[A-Z])(?=.*[a-z])/,
  NUMBER: /\d/,
};

const ValidationIcon = ({ state }: { state: boolean }) =>
  state ? (
    <CheckIcon className="size-5 shrink-0" aria-hidden="true" />
  ) : (
    <span className="flex size-5 shrink-0 items-center justify-center" aria-hidden="true">
      <i className="inline-block size-2 rounded-full bg-slate-700" />
    </span>
  );

export const PasswordChecks = ({ password }: PasswordChecksProps) => {
  const { t } = useTranslation();

  const DEFAULT_VALIDATIONS = useMemo(
    () => [
      { label: t("auth.signup.password_validation_uppercase_and_lowercase"), state: false },
      { label: t("auth.signup.password_validation_minimum_8_and_maximum_128_characters"), state: false },
      { label: t("auth.signup.password_validation_contain_at_least_1_number"), state: false },
    ],
    [t]
  );

  const validations = useMemo(() => {
    if (password === null) return DEFAULT_VALIDATIONS;

    return [
      {
        label: t("auth.signup.password_validation_uppercase_and_lowercase"),
        state: PASSWORD_REGEX.UPPER_AND_LOWER.test(password),
      },
      {
        label: t("auth.signup.password_validation_minimum_8_and_maximum_128_characters"),
        state: password.length >= 8 && password.length <= 128,
      },
      {
        label: t("auth.signup.password_validation_contain_at_least_1_number"),
        state: PASSWORD_REGEX.NUMBER.test(password),
      },
    ];
  }, [password, DEFAULT_VALIDATIONS, t]);

  return (
    // text-sm unconditionally: with only `sm:text-sm` the list rendered *larger* on a phone
    // than on desktop. aria-live announces a rule flipping as the user types (SC 4.1.3).
    <div className="my-2 text-left text-sm text-slate-700">
      <ul aria-label={t("auth.signup.password_requirements")} aria-live="polite">
        {validations.map((validation) => (
          <li key={validation.label} className="flex items-start gap-2">
            <ValidationIcon state={validation.state} />
            <span>{validation.label}</span>
          </li>
        ))}
      </ul>
    </div>
  );
};
"use client";

import { zodResolver } from "@hookform/resolvers/zod";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { FormProvider, useForm } from "react-hook-form";
import toast from "react-hot-toast";
import { useTranslation } from "react-i18next";
import Turnstile, { useTurnstile } from "react-turnstile";
import { z } from "zod";
import {
  INVITE_TOKEN_INVALID_ERROR_CODE,
  PASSWORD_COMPROMISED_ERROR_CODE,
  SIGNUP_EMAIL_DOMAIN_BLOCKED_ERROR_CODE,
} from "@formbricks/types/errors";
import { TUserLocale, ZUserName, ZUserPassword } from "@formbricks/types/user";
import { getFormattedErrorMessage } from "@/lib/utils/error-message";
import { buildAttributionQuerySuffix } from "@/modules/auth/lib/attribution";
import {
  buildSignupWithoutVerificationSuccessPath,
  buildVerificationRequestedPath,
} from "@/modules/auth/lib/verification-links";
import { createUserAction } from "@/modules/auth/signup/actions";
import { TermsPrivacyLinks } from "@/modules/auth/signup/components/terms-privacy-links";
import { SSOOptions } from "@/modules/ee/sso/components/sso-options";
import { Button } from "@/modules/ui/components/button";
import { Checkbox } from "@/modules/ui/components/checkbox";
import { FormControl, FormError, FormField, FormItem, FormLabel } from "@/modules/ui/components/form";
import { Input } from "@/modules/ui/components/input";
import { PasswordInput } from "@/modules/ui/components/password-input";
import { createEmailTokenAction } from "../../../auth/actions";
import { PasswordChecks } from "./password-checks";

const ZSignupInput = z.object({
  name: ZUserName,
  email: z.email(),
  password: ZUserPassword,
});

type TSignupInput = z.infer<typeof ZSignupInput>;

interface SignupFormProps {
  webAppUrl: string;
  privacyUrl: string | undefined;
  termsUrl: string | undefined;
  emailAuthEnabled: boolean;
  googleOAuthEnabled: boolean;
  githubOAuthEnabled: boolean;
  azureOAuthEnabled: boolean;
  oidcOAuthEnabled: boolean;
  oidcDisplayName?: string;
  userLocale: TUserLocale;
  emailFromSearchParams?: string;
  emailVerificationDisabled: boolean;
  isSsoEnabled: boolean;
  samlSsoEnabled: boolean;
  isTurnstileConfigured: boolean;
  turnstileSiteKey?: string;
  isFormbricksCloud: boolean;
}

export const SignupForm = ({
  webAppUrl,
  privacyUrl,
  termsUrl,
  emailAuthEnabled,
  googleOAuthEnabled,
  githubOAuthEnabled,
  azureOAuthEnabled,
  oidcOAuthEnabled,
  oidcDisplayName,
  userLocale,
  emailFromSearchParams,
  emailVerificationDisabled,
  isSsoEnabled,
  samlSsoEnabled,
  isTurnstileConfigured,
  turnstileSiteKey,
  isFormbricksCloud,
}: Readonly<SignupFormProps>) => {
  const [showLogin, setShowLogin] = useState(false);
  const searchParams = useSearchParams();
  const { t } = useTranslation();
  const inviteToken = searchParams?.get("inviteToken");
  const router = useRouter();
  const [turnstileToken, setTurnstileToken] = useState<string>();
  const [subscribeToSecurityUpdates, setSubscribeToSecurityUpdates] = useState(false);
  const [subscribeToProductUpdates, setSubscribeToProductUpdates] = useState(false);

  const turnstile = useTurnstile();

  // An SSO sign-up rejected for a personal email domain redirects back here with ?error=<code>.
  // Match the known code exactly (never echo the raw param). Track the last error value we toasted
  // (rather than a permanent boolean) so strict-mode's double effect invocation and locale re-renders
  // are deduped, but a fresh, distinct rejection value would still notify.
  const oauthError = searchParams?.get("error");
  const lastToastedOauthError = useRef<string | null>(null);
  useEffect(() => {
    if (oauthError !== SIGNUP_EMAIL_DOMAIN_BLOCKED_ERROR_CODE) return;
    if (lastToastedOauthError.current === oauthError) return;
    lastToastedOauthError.current = oauthError;
    toast.error(t("auth.signup.company_email_required"));
  }, [oauthError, t]);

  const returnToUrl = useMemo(() => {
    if (inviteToken) {
      return webAppUrl + "/invite?token=" + inviteToken;
    } else {
      return webAppUrl;
    }
  }, [inviteToken, webAppUrl]);

  const loginHref = useMemo(() => {
    const base = inviteToken ? `/auth/login?callbackUrl=${returnToUrl}` : "/auth/login";
    const attributionSuffix = buildAttributionQuerySuffix(searchParams);
    if (!attributionSuffix) return base;
    return `${base}${base.includes("?") ? "&" : "?"}${attributionSuffix}`;
  }, [inviteToken, returnToUrl, searchParams]);

  const form = useForm<TSignupInput>({
    defaultValues: {
      name: "",
      email: emailFromSearchParams || "",
      password: "",
    },
    resolver: zodResolver(ZSignupInput),
  });

  /**
   * Map a failed `createUserAction` to where the user should see it: the two field-level rejections go
   * under the input that caused them, everything else is a toast. Each stable error code exists so the
   * server can be specific without the message itself being an enumeration signal.
   */
  const surfaceSignupError = (errorMessage: string) => {
    switch (errorMessage) {
      case SIGNUP_EMAIL_DOMAIN_BLOCKED_ERROR_CODE:
        form.setError("email", { type: "manual", message: t("auth.signup.company_email_required") });
        return;
      case PASSWORD_COMPROMISED_ERROR_CODE:
        form.setError("password", { type: "manual", message: t("auth.password_compromised") });
        return;
      case INVITE_TOKEN_INVALID_ERROR_CODE:
        // Reachable when the invite expires or is revoked between this page rendering and the form being
        // submitted. Reuses the existing invite copy rather than naming the specific reason, matching the
        // server, which returns one code for expired / revoked / wrong-address so it cannot be used to
        // probe which invites exist.
        toast.error(t("auth.invite.invite_not_found_description"));
        return;
      default:
        // SIGNUP_DISABLED_ERROR_CODE lands here (#8681). CodeRabbit is right that a real user can see
        // it — sign-up can be open when this page renders and closed before submit, the same
        // render-then-revoke race that makes the invite branch above user-facing — so it should be
        // translated rather than shown as a raw code. Deferred there because adding an en-US string
        // needs the 14 target locales populated too, and doing it without that reddens
        // `scan-translations`; tracked as a follow-up. (This PR hand-writes such strings with their
        // i18n.lock checksums, so that route is open to whoever picks the follow-up up.)
        toast.error(errorMessage);
    }
  };

  const handleSubmit = async (data: TSignupInput) => {
    try {
      if (isTurnstileConfigured && !turnstileToken) {
        throw new Error(t("auth.signup.please_verify_captcha"));
      }

      const resetTurnstileIfConfigured = () => {
        if (isTurnstileConfigured) {
          setTurnstileToken(undefined);
          turnstile.reset();
        }
      };
      const normalizedEmail = data.email.toLowerCase();

      const createUserResponse = await createUserAction({
        name: data.name,
        email: normalizedEmail,
        password: data.password,
        userLocale,
        inviteToken: inviteToken ?? "",
        turnstileToken,
        subscribeToSecurityUpdates,
        subscribeToProductUpdates,
      });

      if (!createUserResponse?.data) {
        resetTurnstileIfConfigured();
        surfaceSignupError(getFormattedErrorMessage(createUserResponse));
        return;
      }

      const emailTokenActionResponse = await createEmailTokenAction({ email: normalizedEmail });
      const token = emailTokenActionResponse?.data;

      if (!token) {
        resetTurnstileIfConfigured();

        const errorMessage = getFormattedErrorMessage(emailTokenActionResponse);
        toast.error(errorMessage);
        return;
      }

      // Both branches carry the invite callback. The verification-disabled branch is the default for
      // self-hosted, so omitting it there left invited users with an existing account unable to reach
      // the invite from the screen they land on (ENG-2091, raised in review).
      const callbackUrl = inviteToken ? returnToUrl : undefined;
      const url = emailVerificationDisabled
        ? buildSignupWithoutVerificationSuccessPath({ token, callbackUrl })
        : buildVerificationRequestedPath({ token, callbackUrl });

      router.push(url);
    } catch (e: any) {
      toast.error(e.message);
    }
  };

  return (
    <div className="text-center">
      <h1 className="mb-4 text-xl font-semibold text-balance text-slate-800">{t("auth.signup.title")}</h1>
      {emailAuthEnabled && (
        <FormProvider {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="mb-2">
            {showLogin && (
              <div>
                <div className="space-y-2">
                  <FormField
                    control={form.control}
                    name="name"
                    render={({ field }) => (
                      <FormItem className="w-full text-left">
                        <FormLabel>{t("common.full_name")}</FormLabel>
                        <FormControl>
                          <Input
                            data-testid="signup-name"
                            value={field.value}
                            name="name"
                            autoComplete="name"
                            autoFocus
                            onBlur={field.onBlur}
                            onChange={(e) => field.onChange(e.target.value)}
                            placeholder="Full name"
                            className="bg-white"
                          />
                        </FormControl>
                        <FormError role="alert" />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem className="w-full text-left">
                        <FormLabel>{t("common.email")}</FormLabel>
                        <FormControl>
                          <Input
                            data-testid="signup-email"
                            type="email"
                            value={field.value}
                            name="email"
                            autoComplete="email"
                            inputMode="email"
                            autoCapitalize="none"
                            autoCorrect="off"
                            spellCheck={false}
                            onBlur={field.onBlur}
                            onChange={(e) => field.onChange(e.target.value)}
                            placeholder="work@email.com"
                            className="bg-white"
                          />
                        </FormControl>
                        <FormError role="alert" />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="password"
                    render={({ field }) => (
                      <FormItem className="w-full text-left">
                        <FormLabel>{t("common.password")}</FormLabel>
                        <FormControl>
                          <PasswordInput
                            data-testid="signup-password"
                            name="password"
                            value={field.value}
                            onBlur={field.onBlur}
                            onChange={(e) => field.onChange(e.target.value)}
                            // This form creates the account, so a password manager should be
                            // offering to generate and store — not autofill the current one.
                            autoComplete="new-password"
                            placeholder="*******"
                            required
                            className="bg-white"
                          />
                        </FormControl>
                        <FormError role="alert" />
                      </FormItem>
                    )}
                  />
                </div>
                <PasswordChecks password={form.watch("password")} />
              </div>
            )}
            {isTurnstileConfigured && showLogin && turnstileSiteKey && (
              // The widget is a fixed 300px-wide iframe, wider than the card's content box on a
              // small phone. "flexible" lets it use the container where there is room; below xs
              // it is scaled to fit, and the clipping wrapper keeps its 300px layout box from
              // widening the page (the scaled content is narrower than the wrapper, so nothing
              // is actually cut off).
              <div data-testid="turnstile-fit" className="mt-4 w-full overflow-hidden">
                <div className="origin-top-left scale-80 xs:origin-top xs:scale-100">
                  <Turnstile
                    sitekey={turnstileSiteKey}
                    size="flexible"
                    onSuccess={(token) => {
                      setTurnstileToken(token);
                    }}
                    onError={() => {
                      setTurnstileToken(undefined);
                      toast.error(t("auth.signup.captcha_failed"));
                    }}
                  />
                </div>
              </div>
            )}

            {showLogin &&
              (isFormbricksCloud ? (
                <label
                  htmlFor="product-updates"
                  className="my-4 flex cursor-pointer items-start gap-x-3 rounded-md border border-slate-200 bg-slate-100 p-3 text-left">
                  <Checkbox
                    id="product-updates"
                    checked={subscribeToProductUpdates}
                    onCheckedChange={(checked) => setSubscribeToProductUpdates(checked === true)}
                    className="mt-0.5 size-4 shrink-0"
                  />
                  <div>
                    <span className="text-sm font-medium text-slate-700">
                      {t("auth.signup.product_updates_title")}
                    </span>
                    <p className="text-xs text-slate-600">{t("auth.signup.product_updates_description")}</p>
                  </div>
                </label>
              ) : (
                <label
                  htmlFor="security-updates"
                  className="my-4 flex cursor-pointer items-start gap-x-3 rounded-md border border-slate-200 bg-slate-100 p-3 text-left">
                  <Checkbox
                    id="security-updates"
                    checked={subscribeToSecurityUpdates}
                    onCheckedChange={(checked) => setSubscribeToSecurityUpdates(checked === true)}
                    className="mt-0.5 size-4 shrink-0"
